141	fn get_valuedata(
142	    value: Value,
143	    program: &mut Program,
144	    my_ir_generator_info: &mut MyIRGeneratorInfo,
145	) -> ValueData {
146	    if value.is_global() {
147	        program.borrow_value(value).clone()
148	    } else {
149	        program
150	            .func(my_ir_generator_info.curr_func.unwrap())
151	            .dfg()
152	            .value(value)
153	            .clone()
154	    }
155	}
