//! Build a single component into Koopa IR.

use crate::ast_def::statements::*;
use koopa::ir::{builder_traits::*, Program, TypeKind};

use super::{
    build_expressions::{build_result_to_value, IRExpBuildResult, IRExpBuildable, IRLValBuildResult},
    create_new_block, create_new_local_value, get_valuedata, insert_basic_blocks,
    insert_local_instructions, IRBuildResult, IRBuildable, MyIRGeneratorInfo,
};

impl IRBuildable for Stmt {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        match &self {
            Stmt::UnmatchedStmt(stmt) => stmt.build(program, my_ir_generator_info),
            Stmt::MatchedStmt(stmt) => stmt.build(program, my_ir_generator_info),
        }
    }
}

impl IRBuildable for UnmatchedStmt {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        self.default.build(program, my_ir_generator_info)
    }
}

impl IRBuildable for MatchedStmt {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        self.default.build(program, my_ir_generator_info)
    }
}

impl IRBuildable for BasicStmt {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        match self {
            BasicStmt::AssignStmt(lval, exp) => {
                let ptr = match lval.build(program, my_ir_generator_info)? {
                    IRLValBuildResult::Addr(ptr) => ptr,
                    IRLValBuildResult::Const(_) => {
                        return Err(format!("Cannot assign to a constant: {:?}", lval))
                    }
                    IRLValBuildResult::TempVal(_) => {
                        return Err(format!("Cannot assign to this LVal: {:?}", lval))
                    }
                };
                // Can only assign to scalars.
                let pointee_is_i32 =
                    match get_valuedata(ptr, program, my_ir_generator_info).ty().kind() {
                        TypeKind::Pointer(base) => base.is_i32(),
                        _ => false,
                    };
                if !pointee_is_i32 {
                    return Err(format!("Cannot assign to an array: {:?}", lval));
                }
                let value = build_result_to_value(
                    exp.build(program, my_ir_generator_info)?,
                    program,
                    my_ir_generator_info,
                );
                let store = create_new_local_value(program, my_ir_generator_info).store(value, ptr);
                insert_local_instructions(program, my_ir_generator_info, [store]);
                Ok(IRBuildResult::OK)
            }
            BasicStmt::Exp(exp) => {
                if let Some(exp) = exp {
                    exp.build(program, my_ir_generator_info)?;
                }
                Ok(IRBuildResult::OK)
            }
            BasicStmt::Block(block) => {
                my_ir_generator_info.symbol_tables.add_new_table();
                block.build(program, my_ir_generator_info)
            }
            BasicStmt::IfStmt(cond_exp, then_stmt, else_stmt) => {
                let cond = build_result_to_value(
                    cond_exp.build(program, my_ir_generator_info)?,
                    program,
                    my_ir_generator_info,
                );
                let then_block = create_new_block(program, my_ir_generator_info, "if_then");
                let end_block = create_new_block(program, my_ir_generator_info, "if_end");
                match else_stmt {
                    Some(else_stmt) => {
                        let else_block = create_new_block(program, my_ir_generator_info, "if_else");
                        let branch = create_new_local_value(program, my_ir_generator_info)
                            .branch(cond, then_block, else_block);
                        insert_local_instructions(program, my_ir_generator_info, [branch]);
                        insert_basic_blocks(
                            program,
                            my_ir_generator_info,
                            [then_block, else_block, end_block],
                        );
                        // Build the then branch.
                        my_ir_generator_info.curr_block = Some(then_block);
                        if let IRBuildResult::OK =
                            then_stmt.build(program, my_ir_generator_info)?
                        {
                            let jump = create_new_local_value(program, my_ir_generator_info)
                                .jump(end_block);
                            insert_local_instructions(program, my_ir_generator_info, [jump]);
                        }
                        // Build the else branch.
                        my_ir_generator_info.curr_block = Some(else_block);
                        if let IRBuildResult::OK =
                            else_stmt.build(program, my_ir_generator_info)?
                        {
                            let jump = create_new_local_value(program, my_ir_generator_info)
                                .jump(end_block);
                            insert_local_instructions(program, my_ir_generator_info, [jump]);
                        }
                    }
                    None => {
                        let branch = create_new_local_value(program, my_ir_generator_info)
                            .branch(cond, then_block, end_block);
                        insert_local_instructions(program, my_ir_generator_info, [branch]);
                        insert_basic_blocks(
                            program,
                            my_ir_generator_info,
                            [then_block, end_block],
                        );
                        // Build the then branch.
                        my_ir_generator_info.curr_block = Some(then_block);
                        if let IRBuildResult::OK =
                            then_stmt.build(program, my_ir_generator_info)?
                        {
                            let jump = create_new_local_value(program, my_ir_generator_info)
                                .jump(end_block);
                            insert_local_instructions(program, my_ir_generator_info, [jump]);
                        }
                    }
                }
                my_ir_generator_info.curr_block = Some(end_block);
                Ok(IRBuildResult::OK)
            }
            BasicStmt::WhileStmt(cond_exp, body_stmt) => {
                let cond_block = create_new_block(program, my_ir_generator_info, "while_cond");
                let body_block = create_new_block(program, my_ir_generator_info, "while_body");
                let end_block = create_new_block(program, my_ir_generator_info, "while_end");
                let jump = create_new_local_value(program, my_ir_generator_info).jump(cond_block);
                insert_local_instructions(program, my_ir_generator_info, [jump]);
                insert_basic_blocks(
                    program,
                    my_ir_generator_info,
                    [cond_block, body_block, end_block],
                );

                // Record the target blocks for break/continue statements.
                my_ir_generator_info.break_tgt_blocks.push(end_block);
                my_ir_generator_info.continue_tgt_blocks.push(cond_block);

