/// Stores the register to `offset(sp)`. Handles both short (12-bit) and
/// long immediate offsets.
fn store_with_offset(&mut self, reg: usize, offset: isize) -> Vec<String> {
    if (MIN_SHORT_INT..=MAX_SHORT_INT).contains(&offset) {
        vec![format!("  sw\t{}, {}(sp)", REGISTER_NAMES[reg], offset)]
    } else {
        vec![
            format!("  li\t{}, {}", REGISTER_NAMES[REG_X31], offset),
            format!(
                "  add\t{}, sp, {}",
                REGISTER_NAMES[REG_X31], REGISTER_NAMES[REG_X31]
            ),
            format!("  sw\t{}, 0({})", REGISTER_NAMES[reg], REGISTER_NAMES[REG_X31]),
        ]
    }
}
/// Loads `offset(sp)` into the register. Handles both short (12-bit) and
/// long immediate offsets.
fn load_with_offset(&mut self, reg: usize, offset: isize) -> Vec<String> {
    if (MIN_SHORT_INT..=MAX_SHORT_INT).contains(&offset) {
        vec![format!("  lw\t{}, {}(sp)", REGISTER_NAMES[reg], offset)]
    } else {
        vec![
            format!("  li\t{}, {}", REGISTER_NAMES[REG_X31], offset),
            format!(
                "  add\t{}, sp, {}",
                REGISTER_NAMES[REG_X31], REGISTER_NAMES[REG_X31]
            ),
            format!("  lw\t{}, 0({})", REGISTER_NAMES[reg], REGISTER_NAMES[REG_X31]),
        ]
    }
}
/// Computes `sp + offset` into the register. Handles both short (12-bit)
/// and long immediate offsets.
fn add_with_offset(&mut self, reg: usize, offset: isize) -> Vec<String> {
    if (MIN_SHORT_INT..=MAX_SHORT_INT).contains(&offset) {
        vec![format!("  addi\t{}, sp, {}", REGISTER_NAMES[reg], offset)]
    } else {
        vec![
            format!("  li\t{}, {}", REGISTER_NAMES[REG_X31], offset),
            format!(
                "  add\t{}, sp, {}",
                REGISTER_NAMES[reg], REGISTER_NAMES[REG_X31]
            ),
        ]
    }
}

