```rust
fn build(&self, program: &Program) -> Result<Vec<String>, String> {
    let mut codes = vec![];
    if self.layout().entry_bb().is_none() { return Ok(codes); }  // declaration
    let func_name = self.name()[1..].to_string();

    // Pre-scan: max extra args and has_call.
    let mut max_extra_args = 0usize;
    let mut has_call = false;
    for (_, node) in self.layout().bbs() {
        for &inst in node.insts().keys() {
            if let ValueKind::Call(call) = self.dfg().value(inst).kind() {
                has_call = true;
                let nargs = call.args().len();
                if nargs > 8 { max_extra_args = max_extra_args.max(nargs - 8); }
            }
        }
    }

    let mut bbvt = MyBBValueTable::new(program, self);
    let extra_area = max_extra_args * ARG_SIZE;
    let mut offset = extra_area;
    // params
    for &param in self.params() {
        bbvt.local_value_location.insert(param, offset);
        offset += ARG_SIZE;
    }
    // locals
    for (_, node) in self.layout().bbs() {
        for &inst in node.insts().keys() {
            let vd = self.dfg().value(inst);
            match vd.kind() {
                ValueKind::Alloc(_) => {
                    let size = match vd.ty().kind() { TypeKind::Pointer(base) => base.size(), _ => 4 };
                    bbvt.local_value_location.insert(inst, offset);
                    offset += size;
                }
                ValueKind::Binary(_) | ValueKind::Load(_) | ValueKind::GetElemPtr(_) | ValueKind::GetPtr(_) => {
                    bbvt.local_value_location.insert(inst, offset);
                    offset += ARG_SIZE;
                }
                ValueKind::Call(_) => {
                    if !vd.ty().is_unit() {
                        bbvt.local_value_location.insert(inst, offset);
                        offset += ARG_SIZE;
                    }
                }
                _ => {}
            }
        }
    }
    let ra_offset = offset;
    if has_call { offset += ARG_SIZE; }
    let frame_size = (offset + 15) / 16 * 16;

    // Prologue
    codes.push("  .text".to_string());
    codes.push(format!("  .globl {}", func_name));
    codes.push(format!("{}:", func_name));
    if frame_size > 0 {
        if (-frame_size as isize) >= MIN_SHORT_INT... addi sp, sp, -frame (imm must be ≥ -2048): frame_size <= 2048 → addi; else li x31, -frame; add sp, sp, x31.
    }
    if has_call { codes.extend(bbvt.store_with_offset(REG_RA, ra_offset as isize)); }
    // params → slots
    for (i, &param) in self.params().iter().enumerate() {
        let off = *bbvt.local_value_location.get(&param).unwrap() as isize;
        if i < 8 {
            codes.extend(bbvt.store_with_offset(REGISTER_FOR_ARGS[i], off));
        } else {
            let src_off = frame_size as isize + (i - 8) as isize * ARG_SIZE as isize;
            codes.extend(bbvt.load_with_offset(REG_X31, src_off));
            codes.extend(bbvt.store_with_offset(REG_X31, off));
        }
    }
    // BBs
    for (&bb, node) in self.layout().bbs() {
        codes.push(format!("{}:", bb_label(&func_name, bb, self)));  // label includes .L prefix
        for &inst in node.insts().keys() {
            let vd = self.dfg().value(inst).clone();
            codes.extend(build_instruction(inst, &vd, self, program, &mut bbvt, &func_name, frame_size, ra_offset, has_call)?);
        }
    }
    Ok(codes)
}
```

